                                 const SessionState& session, const ModelGeometry& g,
                                 const QsaState& draft, std::string& error,
                                 ConversationKvReuse reuse = {}, size_t* reused_bytes = nullptr);
+/// Estimate the snapshot's byte size without capturing. Returns false on geometry mismatch.
+bool conversation_snapshot_estimate(const ConversationView& view, const SessionState& session,
+                                    const ModelGeometry& g, const QsaState& draft,
+                                    size_t& bytes, std::string& error);
+
